const input = $input.first().json;
const target = (input.query || input.target || '').trim();

const isValid = /^[a-zA-Z0-9][a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$/.test(target);

if (!isValid || target.length < 4) {
  return [{ json: { error: true, output: '❌ Invalid target. Provide a valid domain (e.g., example.com).' } }];
}

return [{ json: { target, error: false } }];

const target = $('Validate Target').first().json.target;
const headers = $('Check HTTP Headers').first().json;
const tavily = $('Tavily Threat Intel').first().json;

// Analyze security headers
const hdrs = headers.headers || {};
const securityHeaders = {
  'Strict-Transport-Security': hdrs['strict-transport-security'] || '❌ Missing',
  'Content-Security-Policy': hdrs['content-security-policy'] ? '✅ Present' : '❌ Missing',
  'X-Frame-Options': hdrs['x-frame-options'] || '❌ Missing',
  'X-Content-Type-Options': hdrs['x-content-type-options'] || '❌ Missing',
  'X-XSS-Protection': hdrs['x-xss-protection'] || '⚠️ Deprecated (use CSP)',
  'Referrer-Policy': hdrs['referrer-policy'] || '❌ Missing'
};

const headerReport = Object.entries(securityHeaders)
  .map(([k, v]) => `• ${k}: ${v}`).join('\n');

// Tavily results
const threats = (tavily.results || []).slice(0, 3)
  .map(r => `• ${r.title}\n  ${r.url}`).join('\n') || 'No known threats found.';

const output = `🔍 **Security Scan: ${target}**\n\n` +
  `**HTTP Status:** ${headers.statusCode || 'N/A'}\n` +
  `**Server:** ${hdrs.server || 'Hidden'}\n\n` +
  `**Security Headers:**\n${headerReport}\n\n` +
  `**Threat Intelligence:**\n${threats}\n\n` +
  `⚠️ This is a passive scan. For active testing, use authorized pentest tools.`;

return [{ json: { output } }];
